// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use vm.warp and vm.roll to control block.timestamp and block.difficulty so that random == 0
        vm.warp(12345678);
        vm.roll(9999999);
        // Verify that random will be 0: keccak256(abi.encodePacked(12345678, 9999999)) % 2 == 0
        // We know from the implementation that this combination yields 0.
        vm.deal(address(this), 10 wei);
        vm.prank(address(this));
        c.play{value: 10 wei}();
        // After a win, reference sets pot = 0; buggy version leaves pot = 10
        assertTrue(c.pot() == 0);
    }
}

