pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set block.timestamp to force random == 0 (keccak256(abi.encodePacked(block.timestamp, block.difficulty)) % 2 == 0)
        // We'll warp to a specific timestamp that yields 0 after testing; here we assume timestamp=1 with difficulty=0 gives 0.
        vm.warp(1);
        vm.roll(0); // block.difficulty = 0

        // Fund the caller
        address player = address(0x1234);
        vm.deal(player, 10 ether);

        // Record bank balance before
        address bank = c.bank();
        uint bankBalanceBefore = bank.balance;

        // Player calls play() exactly once
        vm.prank(player);
        c.play{value: 10 ether}();

        // After call, bank balance should be 1 wei higher in reference (FEE_AMOUNT = 1 wei)
        uint bankBalanceAfter = bank.balance;

        // Assert that bank received exactly 1 wei (FEE_AMOUNT) — in the buggy version, bank gets less.
        assertTrue(bankBalanceAfter - bankBalanceBefore == 1);
    }
}

